CREATE DATABASE IF NOT EXISTS signfix CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE signfix;
CREATE TABLE roles(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(50) UNIQUE NOT NULL);
CREATE TABLE users(id BIGINT PRIMARY KEY AUTO_INCREMENT,role_id BIGINT NOT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,mobile VARCHAR(20),password_hash VARCHAR(255) NOT NULL,status ENUM('active','disabled') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE customers(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNIQUE NOT NULL,company_name VARCHAR(160),address JSON,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE technicians(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNIQUE NOT NULL,service_areas JSON,location_sharing BOOLEAN DEFAULT FALSE,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE products(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160) NOT NULL,category VARCHAR(100),description TEXT,pricing_method ENUM('sqft','unit','fixed') NOT NULL,status BOOLEAN DEFAULT TRUE);
CREATE TABLE pricing_rules(id BIGINT PRIMARY KEY AUTO_INCREMENT,product_id BIGINT,rule_type VARCHAR(50),amount DECIMAL(12,2) NOT NULL,tax_rate DECIMAL(5,2) DEFAULT 18,active BOOLEAN DEFAULT TRUE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE orders(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_no VARCHAR(30) UNIQUE NOT NULL,customer_id BIGINT NOT NULL,specifications JSON NOT NULL,estimated_price DECIMAL(12,2),status VARCHAR(40) DEFAULT 'under_review',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE quotations(id BIGINT PRIMARY KEY AUTO_INCREMENT,quotation_no VARCHAR(30) UNIQUE NOT NULL,order_id BIGINT NOT NULL,subtotal DECIMAL(12,2),discount DECIMAL(12,2),gst DECIMAL(12,2),final_amount DECIMAL(12,2) NOT NULL,terms TEXT,valid_until DATE,admin_approved_at DATETIME,status VARCHAR(30),FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE service_tickets(id BIGINT PRIMARY KEY AUTO_INCREMENT,ticket_no VARCHAR(30) UNIQUE NOT NULL,customer_id BIGINT NOT NULL,category VARCHAR(80),description TEXT,location JSON,photos JSON,priority VARCHAR(20),status VARCHAR(40) DEFAULT 'submitted',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE technician_jobs(id BIGINT PRIMARY KEY AUTO_INCREMENT,ticket_id BIGINT NOT NULL,technician_id BIGINT,status VARCHAR(40),scheduled_at DATETIME,evidence JSON,customer_confirmation JSON,FOREIGN KEY(ticket_id) REFERENCES service_tickets(id),FOREIGN KEY(technician_id) REFERENCES technicians(id));
CREATE TABLE sign_board_assets(id BIGINT PRIMARY KEY AUTO_INCREMENT,asset_no VARCHAR(20) UNIQUE NOT NULL,customer_id BIGINT NOT NULL,details JSON NOT NULL,location JSON,warranty_until DATE,qr_token CHAR(64) UNIQUE NOT NULL,FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE ai_conversations(id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT,messages JSON,escalated BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ai_leads(id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT,requirement JSON,budget DECIMAL(12,2),status ENUM('new','contacted','qualified','quotation','won','lost') DEFAULT 'new');
CREATE TABLE notifications(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,channel VARCHAR(20),title VARCHAR(160),body TEXT,read_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,action VARCHAR(100),entity_type VARCHAR(60),entity_id BIGINT,metadata JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE job_status_history(id BIGINT PRIMARY KEY AUTO_INCREMENT,job_id BIGINT NOT NULL,status VARCHAR(40) NOT NULL,notes TEXT,created_by BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(job_id) REFERENCES technician_jobs(id));
CREATE TABLE job_photos(id BIGINT PRIMARY KEY AUTO_INCREMENT,job_id BIGINT NOT NULL,photo_type ENUM('before','work','after') NOT NULL,storage_key VARCHAR(255) NOT NULL,mime_type VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(job_id) REFERENCES technician_jobs(id));
CREATE TABLE asset_service_history(id BIGINT PRIMARY KEY AUTO_INCREMENT,asset_id BIGINT NOT NULL,ticket_id BIGINT,summary TEXT,serviced_at DATETIME,FOREIGN KEY(asset_id) REFERENCES sign_board_assets(id),FOREIGN KEY(ticket_id) REFERENCES service_tickets(id));
CREATE TABLE design_requests(id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT NOT NULL,order_id BIGINT,brief JSON NOT NULL,status VARCHAR(30) DEFAULT 'requested',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE design_concepts(id BIGINT PRIMARY KEY AUTO_INCREMENT,request_id BIGINT NOT NULL,storage_key VARCHAR(255),prompt TEXT,is_customer_selected BOOLEAN DEFAULT FALSE,admin_status VARCHAR(30) DEFAULT 'pending',FOREIGN KEY(request_id) REFERENCES design_requests(id));
CREATE TABLE settings(id BIGINT PRIMARY KEY AUTO_INCREMENT,setting_key VARCHAR(120) UNIQUE NOT NULL,value JSON NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE INDEX idx_orders_customer_status ON orders(customer_id,status);
CREATE INDEX idx_tickets_customer_status ON service_tickets(customer_id,status);
CREATE INDEX idx_jobs_technician_status ON technician_jobs(technician_id,status);
CREATE TABLE permissions(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) UNIQUE NOT NULL,description VARCHAR(255));
CREATE TABLE role_permissions(role_id BIGINT NOT NULL,permission_id BIGINT NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE product_categories(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) UNIQUE NOT NULL,status BOOLEAN DEFAULT TRUE);
CREATE TABLE materials(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) UNIQUE NOT NULL,price_per_sqft DECIMAL(12,2) DEFAULT 0,status BOOLEAN DEFAULT TRUE);
CREATE TABLE lighting_options(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) UNIQUE NOT NULL,price_per_sqft DECIMAL(12,2) DEFAULT 0,status BOOLEAN DEFAULT TRUE);
CREATE TABLE order_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,product_id BIGINT,quantity INT NOT NULL DEFAULT 1,dimensions JSON,material_id BIGINT,lighting_option_id BIGINT,unit_price DECIMAL(12,2),estimated_total DECIMAL(12,2),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(material_id) REFERENCES materials(id),FOREIGN KEY(lighting_option_id) REFERENCES lighting_options(id));
CREATE TABLE quotation_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,quotation_id BIGINT NOT NULL,description VARCHAR(255) NOT NULL,quantity DECIMAL(10,2) DEFAULT 1,unit_price DECIMAL(12,2) NOT NULL,total DECIMAL(12,2) NOT NULL,FOREIGN KEY(quotation_id) REFERENCES quotations(id) ON DELETE CASCADE);
CREATE TABLE service_categories(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) UNIQUE NOT NULL,status BOOLEAN DEFAULT TRUE);
CREATE TABLE qr_codes(id BIGINT PRIMARY KEY AUTO_INCREMENT,asset_id BIGINT UNIQUE NOT NULL,token_hash CHAR(64) UNIQUE NOT NULL,expires_at DATETIME,revoked_at DATETIME,FOREIGN KEY(asset_id) REFERENCES sign_board_assets(id) ON DELETE CASCADE);
CREATE TABLE ai_knowledge_base(id BIGINT PRIMARY KEY AUTO_INCREMENT,category VARCHAR(80),question TEXT,answer TEXT NOT NULL,status BOOLEAN DEFAULT TRUE,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE payments(id BIGINT PRIMARY KEY AUTO_INCREMENT,quotation_id BIGINT NOT NULL,provider VARCHAR(60),provider_reference VARCHAR(190),amount DECIMAL(12,2) NOT NULL,status VARCHAR(30) NOT NULL,paid_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(quotation_id) REFERENCES quotations(id));
CREATE TABLE reviews(id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT NOT NULL,job_id BIGINT,rating TINYINT NOT NULL,comments TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CHECK(rating BETWEEN 1 AND 5),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(job_id) REFERENCES technician_jobs(id));
